-- 2. Update Article Kompensasi Layanan (id 14)
UPDATE #__content
SET introtext = '<nav class="svc-subnav" aria-label="Navigasi Layanan Publik"><a href="/layanan-publik">Layanan Publik</a><a href="/jenis-layanan-ptsp">Layanan PTSP</a><a href="/standar-pelayanan">Standar Pelayanan</a><a href="/maklumat-pelayanan">Maklumat</a><a href="/kompensasi-layanan" aria-current="page">Kompensasi</a><a href="/layanan-disabilitas">Disabilitas</a><a href="/permohonan-informasi">Permohonan Informasi</a><a href="/regulasi-pengaduan">Pengaduan</a></nav><div class="svc-hero svc-hero--information"><div><span class="svc-kicker">Jaminan Layanan</span><p class="svc-lead">Berdasarkan Surat Keputusan Ketua Pengadilan Negeri Natuna Nomor <strong>54/KPN.W32-U4/SK.KP7.1/IX/2026</strong> tentang Kompensasi Keterlambatan Pelayanan, Pengadilan Negeri Natuna berkomitmen memberikan kompensasi kepada pengguna layanan apabila terjadi keterlambatan dalam pemberian pelayanan publik.</p><ul class="svc-facts"><li>SK KPN Natuna No. 54/IX/2026</li><li>Hak Anda Mendapatkan Pelayanan Tepat Waktu</li></ul></div><svg class="svc-illus" viewBox="0 0 200 160" aria-hidden="true"><circle cx="100" cy="80" r="72" fill="#fbf2d8"/><path d="M100 26l42 15v30c0 28-42 47-42 47s-42-19-42-47V41z" fill="#8f1f0b"/><path d="M100 36l32 11v24c0 21-32 36-32 36s-32-15-32-36V47z" fill="#671607"/><path d="M100 62c4-7 14-7 17 0 3 6-3 12-17 22-14-10-20-16-17-22 3-7 13-7 17 0z" fill="#b98f24"/><circle cx="150" cy="42" r="5" fill="#b98f24"/><circle cx="52" cy="56" r="4" fill="#b98f24"/><circle cx="146" cy="98" r="4" fill="#1f5b4b" opacity="0.5"/><ellipse cx="100" cy="136" rx="58" ry="5" fill="#1f5b4b" opacity="0.18"/></svg></div><h2>Bentuk Kompensasi Keterlambatan</h2><div class="svc-grid"><div class="svc-card svc-card--reward"><span class="svc-card__duration">30 &ndash; 60 Menit</span><span class="svc-icon"><svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"><path d="M17 3a2.828 2.828 0 1 1 4 4L7.5 20.5 2 22l1.5-5.5L17 3z"/></svg></span><h3>Pena</h3><p>Pemberian cinderamata berupa Pena resmi Pengadilan Negeri Natuna serta permohonan maaf atas keterlambatan pelayanan.</p></div><div class="svc-card svc-card--reward"><span class="svc-card__duration">61 &ndash; 120 Menit</span><span class="svc-icon"><svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"><path d="M18 8h1a4 4 0 0 1 0 8h-1"/><path d="M2 8h16v9a4 4 0 0 1-4 4H6a4 4 0 0 1-4-4V8z"/><line x1="6" y1="1" x2="6" y2="4"/><line x1="10" y1="1" x2="10" y2="4"/><line x1="14" y1="1" x2="14" y2="4"/></svg></span><h3>Gelas</h3><p>Pemberian cinderamata berupa Mug/Gelas resmi Pengadilan Negeri Natuna serta permohonan maaf atas keterlambatan pelayanan.</p></div><div class="svc-card svc-card--reward"><span class="svc-card__duration">&gt; 120 Menit</span><span class="svc-icon"><svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"><path d="M17 3a2.828 2.828 0 1 1 4 4L7.5 20.5 2 22l1.5-5.5L17 3z"/><path d="M18 8h1a4 4 0 0 1 0 8h-1"/><path d="M2 8h16v9a4 4 0 0 1-4 4H6a4 4 0 0 1-4-4V8z"/></svg></span><h3>Pena &amp; Gelas</h3><p>Pemberian paket cinderamata berupa Pena dan Gelas resmi Pengadilan Negeri Natuna serta penanganan prioritas.</p></div></div><h2>Cara Menyampaikan Keluhan</h2><ol class="svc-steps"><li><strong>Sampaikan keluhan Anda</strong><span>Melalui petugas PTSP, meja pengaduan, atau aplikasi SIWAS MA RI dengan menyertakan bukti pendaftaran layanan.</span></li><li><strong>Verifikasi oleh petugas</strong><span>Petugas memeriksa kesesuaian waktu penyelesaian layanan dengan standar waktu yang ditetapkan.</span></li><li><strong>Kompensasi diserahkan</strong><span>Apabila terjadi keterlambatan sesuai kategori durasi, kompensasi berupa permohonan maaf dan souvenir diserahkan langsung kepada pengguna layanan.</span></li></ol><h2>Dokumen SK Kompensasi Layanan</h2><button type="button" class="svc-zoom svc-document-preview svc-document-preview--landscape" data-maklumat-zoom="/images/layanan/sk-kompensasi-pelayanan-2026.webp" data-maklumat-label="SK Kompensasi Keterlambatan Pelayanan Pengadilan Negeri Natuna — SK No. 54/KPN.W32-U4/SK.KP7.1/IX/2026" aria-label="Perbesar dokumen SK kompensasi layanan"><img src="/images/layanan/sk-kompensasi-pelayanan-2026.webp" srcset="/images/layanan/sk-kompensasi-pelayanan-2026-thumb.webp 400w, /images/layanan/sk-kompensasi-pelayanan-2026-800.webp 800w, /images/layanan/sk-kompensasi-pelayanan-2026.webp 1772w" sizes="(max-width: 760px) 92vw, 720px" width="1772" height="1016" alt="SK Kompensasi Keterlambatan Pelayanan Pengadilan Negeri Natuna" loading="lazy" decoding="async"><span class="svc-zoom-hint" aria-hidden="true"><svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round"><circle cx="11" cy="11" r="7"/><path d="m21 21-4.3-4.3"/><path d="M11 8v6M8 11h6"/></svg>Klik untuk perbesar</span></button><div class="svc-cta"><div><h2>Layanan kami belum sesuai harapan?</h2><p>Sampaikan pengaduan Anda &#8212; setiap masukan membantu kami memperbaiki mutu pelayanan.</p></div><div class="svc-cta-buttons"><a class="svc-btn svc-btn-gold" href="/regulasi-pengaduan"><svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"><polygon points="11 5 6 9 2 9 2 15 6 15 11 19 11 5"/><path d="M15.54 8.46a5 5 0 0 1 0 7.07"/></svg>Kanal Pengaduan</a><a class="svc-btn svc-btn-line" href="https://wa.me/6281261256661" target="_blank" rel="noopener"><svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"><path d="M21 15a2 2 0 0 1-2 2H7l-4 4V5a2 2 0 0 1 2-2h14a2 2 0 0 1 2 2z"/></svg>WhatsApp Kami</a></div></div>',
    modified = UTC_TIMESTAMP(),
    modified_by = 0
WHERE id = 14
